/* ------------------------------ render ----------------------------- */
const cv=document.getElementById('c'), ctx=cv.getContext('2d');
function drawSprite(sp,x,y,flip){ const h=sp.rows.length,w=sp.w,ox=Math.floor(x-w/2),oy=Math.floor(y-h/2);
